fn concat(a: &[i32], b: &[i32]) -> Vec<i32> {
    // Pre-allocate a vector with enough capacity for both slices
    let mut result = Vec::with_capacity(a.len() + b.len());
    // Extend with elements from the first slice
    result.extend_from_slice(a);
    // Extend with elements from the second slice
    result.extend_from_slice(b);
    result
}

